#!/bin/bash
set -e
DIR="$( cd "$( dirname "${BASH_SOURCE[0]}" )" >/dev/null && pwd )"
source ${DIR}/../../scripts/utils.sh
source ${DIR}/cfk-day2-utils.bash

# PLAINTEXT to SASL_SSL on a running cluster deployed by Confluent for Kubernetes, with a producer and a sink connector
# running through it, and the three mistakes met on the way:
#   1. a CLIENT listener SASL_SSL (certificates generated by CFK from our CA), the producer moved to it
#   2. the INTERNAL listener switched alone: the CR says RUNNING, the operator never applies it (ApplyFailed)
#   3. with the metric reporter fixed: the REPLICATION listener (inter-broker) inherits the security of INTERNAL, the
#      inter-broker protocol changes in the same roll: while it rolls the followers can't fetch, acks=all producers get
#      NotEnoughReplicasException
#   4. connect and schema registry still talk PLAINTEXT to INTERNAL: their CRs say RUNNING, they reach no broker. Fixed
#      in their CRs (dependencies.kafka: authentication, tls)
#   5. the client nobody moved (legacy) stops
day2_require_cfk
KAFKA_FQDN="kafka.confluent.svc.cluster.local"
CLIENT_CONFIG="/tmp/day2-sasl-ssl.properties"

function day2_cfk_patch_expect_failure () {
    # playground cfk patch, which must fail: $1 resource, $2 patch, $3 timeout; the output in DAY2_PATCH_OUTPUT
    local out rc
    out=$(mktemp)
    set +e
    playground cfk patch "$1" "$2" --timeout "$3" 2>&1 | tee "$out"
    rc=${PIPESTATUS[0]}
    set -e
    DAY2_PATCH_OUTPUT=$(cat "$out")
    rm -f "$out"
    if [ "$rc" -eq 0 ]
    then
        logerror "❌ expected playground cfk patch $1 to fail"
        exit 1
    fi
}

function day2_acks_since () {
    # acks of a producer ($2 name) since epoch millis $1
    day2_client "grep '\"producer_send_success\"' /tmp/day2-${2:-producer}.log" 2> /dev/null | jq -r --argjson since "$1" 'select(.timestamp >= $since) | .timestamp' | wc -l | tr -d ' '
}

function day2_listeners () {
    log_command kubectl -n confluent exec kafka-0 -c kafka -- grep -E '^(listeners|listener.security.protocol.map)=' /opt/confluentinc/etc/kafka/kafka.properties
    kubectl -n confluent exec kafka-0 -c kafka -- sh -c "grep -E '^(listeners|listener.security.protocol.map)=' /opt/confluentinc/etc/kafka/kafka.properties" | sed 's/^/   /'
}

log "Step 1: Confluent Platform $TAG deployed by CFK, 3 KRaft controllers, 3 brokers, schema registry, connect, every listener PLAINTEXT"
day2_start_cfk
day2_listeners

log "Step 2: a workload, and a second producer nobody will move (legacy), both on the INTERNAL listener (PLAINTEXT, 9071)"
day2_start_workload
day2_start_producer legacy
sleep 10

log "Step 3: the secrets (CA for the certificates CFK generates, SASL/PLAIN users), then a CLIENT listener SASL_SSL on 9093"
ca_dir=$(mktemp -d)
log_command openssl req -x509 -newkey rsa:2048 -nodes -keyout ca-key.pem -out ca.pem -days 30 -subj /CN=day2-ca
openssl req -x509 -newkey rsa:2048 -nodes -keyout "$ca_dir/ca-key.pem" -out "$ca_dir/ca.pem" -days 30 -subj "/CN=day2-ca" 2> /dev/null
kubectl -n confluent delete secret ca-pair-sslcerts credential connect-credential schemaregistry-credential --ignore-not-found > /dev/null
run_logged kubectl -n confluent create secret tls ca-pair-sslcerts --cert="$ca_dir/ca.pem" --key="$ca_dir/ca-key.pem"
# plain-users.json: the users of the listeners; plain-interbroker.txt and plain.txt: the clients of the brokers themselves
run_logged kubectl -n confluent create secret generic credential \
    --from-literal=plain-users.json='{"kafka": "kafka-secret", "client": "client-secret", "connect": "connect-secret", "schemaregistry": "schemaregistry-secret"}' \
    --from-literal=plain-interbroker.txt="$(printf 'username=kafka\npassword=kafka-secret')" \
    --from-literal=plain.txt="$(printf 'username=kafka\npassword=kafka-secret')"
playground cfk patch kafka/kafka '{"spec": {"tls": {"autoGeneratedCerts": true}, "listeners": {"custom": [{"name": "client", "port": 9093, "authentication": {"type": "plain", "jaasConfig": {"secretRef": "credential"}}, "tls": {"enabled": true}}]}}}'
day2_listeners

log "Step 4: the producer moved to the CLIENT listener (SASL_SSL, the CA as a PEM truststore)"
log_command kubectl -n confluent exec -i "$DAY2_CLIENT_POD" -- sh -c 'cat > /tmp/ca.pem' '<' ca.pem
kubectl -n confluent exec -i "$DAY2_CLIENT_POD" -- sh -c 'cat > /tmp/ca.pem' < "$ca_dir/ca.pem"
client_properties='security.protocol=SASL_SSL
sasl.mechanism=PLAIN
sasl.jaas.config=org.apache.kafka.common.security.plain.PlainLoginModule required username="client" password="client-secret";
ssl.truststore.type=PEM
ssl.truststore.location=/tmp/ca.pem'
echo "$client_properties" | sed 's/^/   /'
echo "$client_properties" | kubectl -n confluent exec -i "$DAY2_CLIENT_POD" -- sh -c "cat > $CLIENT_CONFIG"
rm -rf "$ca_dir"
day2_stop_producers producer
day2_start_producer producer "$DAY2_TOPIC" "$KAFKA_FQDN:9093" "$CLIENT_CONFIG"
sleep 15
day2_report_workload "on the CLIENT listener"

log "Step 5: the first mistake, the INTERNAL listener switched to SASL_SSL alone"
since=$(day2_now)
day2_cfk_patch_expect_failure kafka/kafka '{"spec": {"listeners": {"internal": {"authentication": {"type": "plain", "jaasConfig": {"secretRef": "credential"}}, "tls": {"enabled": true}}}}}' 300
apply_failed=$(echo "$DAY2_PATCH_OUTPUT" | grep -c "ApplyFailed" || true)
log "💥 kubectl patch said 'patched', the CR still says $(kubectl -n confluent get kafka kafka -o jsonpath='{.status.phase}'): the operator fails to apply it on every reconcile, nothing rolls"
day2_listeners

log "Step 6: the second mistake, the metric reporter fixed (TLS and SASL/PLAIN): the brokers roll, and REPLICATION (inter-broker) follows INTERNAL in the same roll"
errors_before=$(day2_send_errors)
since=$(day2_now)
playground cfk patch kafka/kafka '{"spec": {"metricReporter": {"enabled": true, "authentication": {"type": "plain", "jaasConfig": {"secretRef": "credential"}}, "tls": {"enabled": true}}}}' --timeout 1200
errors_brokers=$(( $(day2_send_errors) - errors_before ))
pause_brokers=$(day2_longest_pause "$since")
day2_listeners
final_map=$(kubectl -n confluent exec kafka-0 -c kafka -- sh -c "grep '^listener.security.protocol.map=' /opt/confluentinc/etc/kafka/kafka.properties" 2> /dev/null || true)
log "🕐 send errors per minute during that roll:"
day2_error_timeline "$since"
log "💥 nobody asked for it: REPLICATION has no security of its own in the Kafka CR, so it inherits the one of INTERNAL. The inter-broker protocol changed in one roll: while some brokers replicate in SASL_SSL and the others in PLAINTEXT, the followers can't fetch, the ISR shrinks below min.insync.replicas: $errors_brokers send errors, ${pause_brokers}s without an ack (the earlier rolls: one or two errors each). Pin spec.listeners.replication to keep the inter-broker change out of it"
since_internal=$(day2_now)

log "Step 7: the third mistake, connect and schema registry still talk PLAINTEXT to INTERNAL"
sleep 30
log_command kubectl -n confluent get connect,schemaregistry
kubectl -n confluent get connect,schemaregistry | sed 's/^/   /'
log_command kubectl -n confluent logs connect-0 -c connect --since=60s
connect_errors=$(kubectl -n confluent logs connect-0 -c connect --since=60s 2> /dev/null | grep -c "could not be established" || true)
log "💥 the CRs say RUNNING, the pods are Ready, and connect logged $connect_errors 'Connection to node … (…:9071) could not be established' in the last minute"

log "Step 8: the fix, in the Connect and SchemaRegistry CRs: dependencies.kafka with SASL/PLAIN and TLS (and a truststore from the CA)"
for component in connect schemaregistry
do
    run_logged kubectl -n confluent create secret generic "$component-credential" --from-literal=plain.txt="$(printf 'username=%s\npassword=%s-secret' "$component" "$component")"
    playground cfk patch "$component/$component" "{\"spec\": {\"tls\": {\"autoGeneratedCerts\": true}, \"dependencies\": {\"kafka\": {\"bootstrapEndpoint\": \"$KAFKA_FQDN:9071\", \"authentication\": {\"type\": \"plain\", \"jaasConfig\": {\"secretRef\": \"$component-credential\"}}, \"tls\": {\"enabled\": true}}}}}"
done
sleep 30
connect_errors_after=$(kubectl -n confluent logs connect-0 -c connect --since=30s 2> /dev/null | grep -c "could not be established" || true)
log_command kubectl -n confluent exec connect-0 -c connect -- grep -E '^(bootstrap.servers|security.protocol)=' /opt/confluentinc/etc/connect/connect.properties
kubectl -n confluent exec connect-0 -c connect -- sh -c "grep -E '^(bootstrap.servers|security.protocol)=' /opt/confluentinc/etc/connect/connect.properties" | sed 's/^/   /'
log "🔎 connect: $connect_errors_after connection errors in the last 30 s"
# the REST API of connect is https now (spec.tls of the Connect CR): the Connector CR says what the worker reports
run_logged kubectl -n confluent get connector day2-sink

log "Step 9: the client nobody moved"
legacy_acks=$(day2_acks_since "$since_internal" legacy)
log "💥 legacy producer: $legacy_acks acks since INTERNAL is SASL_SSL, what it logs:"
log_command kubectl -n confluent exec "$DAY2_CLIENT_POD" -- tail -1 /tmp/day2-legacy.log
legacy_symptom=$(day2_client "grep -E 'OutOfMemoryError|could not be established|disconnected' /tmp/day2-legacy.log | tail -1" 2> /dev/null | cut -c1-250 || true)
echo "   $legacy_symptom"
if [[ "$legacy_symptom" == *"OutOfMemoryError"* ]]
then
    log "   a PLAINTEXT client reads the first bytes of the TLS handshake as the size of a response, and allocates it (KAFKA-4090): 'our producers run out of memory after we enabled TLS'"
fi
day2_stop_producers legacy

log "Step 10: no record lost (checked through the CLIENT listener: the playground commands use INTERNAL in PLAINTEXT)"
DAY2_CLIENT_CONFIG="$CLIENT_CONFIG"
DAY2_CHECK_BOOTSTRAP="$KAFKA_FQDN:9093"
day2_check_no_loss
log "📋 send errors of the producer during the roll that switched INTERNAL and REPLICATION: $errors_brokers (longest pause ${pause_brokers}s); connect errors before / after its fix: $connect_errors / $connect_errors_after; legacy acks after the switch: $legacy_acks"
if [ "$apply_failed" -eq 0 ] || [[ "$final_map" != *"INTERNAL:SASL_SSL"* ]] || [[ "$final_map" != *"REPLICATION:SASL_SSL"* ]] || [ "$connect_errors" -eq 0 ] || [ "$connect_errors_after" -ne 0 ] || [ "$legacy_acks" -ne 0 ]
then
    logerror "❌ expected: ApplyFailed for INTERNAL alone ($apply_failed), INTERNAL and REPLICATION in SASL_SSL ($final_map), connect failing before its fix ($connect_errors) and not after ($connect_errors_after), the legacy producer stopped ($legacy_acks acks)"
    exit 1
fi
